package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class ReorderShoppingItemsUseCase{private final ShoppingListRepository lists;private final ShoppingItemRepository items;private final ShoppingListHouseholdAccessPort access;private final Clock clock;public ReorderShoppingItemsUseCase(ShoppingListRepository l,ShoppingItemRepository i,ShoppingListHouseholdAccessPort a,Clock c){lists=l;items=i;access=a;clock=c;}public ShoppingList execute(Long actor,UUID h,UUID listId,long revision,List<UUID> order){access.getContext(h,actor);var list=GetShoppingListUseCase.load(lists,listId,h);list.requireActive();if(list.contentRevision()!=revision)throw new ShoppingListConflictException("Shopping list content changed concurrently");var pending=items.list(listId).stream().filter(x->x.status()==ShoppingItemStatus.PENDING).collect(Collectors.toMap(ShoppingItem::id,Function.identity()));if(order.size()!=pending.size()||!pending.keySet().equals(new HashSet<>(order)))throw new ShoppingListConflictException("Pending item order is stale");if(!lists.advanceContentRevision(listId,revision,clock.instant()))throw new ShoppingListConflictException("Shopping list content changed concurrently");for(int index=0;index<order.size();index++){var item=pending.get(order.get(index));item.moveTo(index,clock.instant());items.save(item);}return GetShoppingListUseCase.load(lists,listId,h);}}
